IF SCHEMA_ID(N'AttackData') IS NULL
    EXEC (N'CREATE SCHEMA AttackData');
go

create table AttackData.Action
(
    ActionName    nvarchar(50) not null,
    ActionType    nvarchar(50) not null,
    ActionComboID int          not null,
    constraint PK_AttackData_Action
        primary key (ActionName, ActionType, ActionComboID)
)
go

create table AttackData.Class
(
    ClassName nvarchar(50) not null
        constraint PK_ClassName
            primary key
)
go

create table AttackData.Enemy
(
    EnemyType nvarchar(50) not null
        constraint PK_AttackData_Enemy
            primary key
)
go

create table AttackData.Hit
(
    HitType nvarchar(50) not null
        constraint PK_AttackData_Hit
            primary key
)
go

create table AttackData.Weapon
(
    WeaponName nvarchar(100) not null
        constraint PK_Weapon_WeaponName
            primary key
)
go

create table AttackData.ClassWeapon
(
    ClassName  nvarchar(50)  not null
        constraint FK_ClassWeapon_ClassName
            references AttackData.Class,
    WeaponName nvarchar(100) not null
        constraint FK_ClassWeapon_WeaponName
            references AttackData.Weapon,
    constraint PK_ClassWeapon
        primary key (ClassName, WeaponName)
)
go

create table AttackData.Damage
(
    DamageID      int identity
        constraint PK_Damage
            primary key,
    DamageNumbLow int           not null,
    DamageNumbHi  int           not null,
    WeaponName    nvarchar(100) not null
        references AttackData.Weapon,
    EnemyType     nvarchar(50)  not null
        references AttackData.Enemy,
    HitType       nvarchar(50)  not null
        references AttackData.Hit,
    ActionName    nvarchar(50)  not null,
    ActionType    nvarchar(50)  not null,
    ActionComboID int           not null,
    constraint UQ_Damage_Combo
        unique (WeaponName, EnemyType, HitType, ActionName, ActionType, ActionComboID),
    foreign key (ActionName, ActionType, ActionComboID) references AttackData.Action,
    constraint CK_Damage_Range
        check ([DamageNumbLow] <= [DamageNumbHi])
)
go

-- Damage data:
-- Darktide damage data. Generated from the game's weapon stat code (https://github.com/aussiemon/Darktide-Source-Code)
-- patch 1.13.4.
-- DamageNumbLow = weapon stats at 0%, DamageNumbHi = weapon stats at 100%.

INSERT INTO AttackData.Enemy (EnemyType)
SELECT v.EnemyType
FROM (VALUES
    (N'Unarmoured'),
    (N'Infested'),
    (N'Flak Armoured'),
    (N'Unyielding'),
    (N'Carapace Armoured'),
    (N'Maniac')
) AS v(EnemyType)
WHERE NOT EXISTS (SELECT 1 FROM AttackData.Enemy t WHERE t.EnemyType = v.EnemyType);
GO

INSERT INTO AttackData.Hit (HitType)
SELECT v.HitType
FROM (VALUES
    (N'Body'),
    (N'Weakspot'),
    (N'Critical'),
    (N'Critical Weakspot')
) AS v(HitType)
WHERE NOT EXISTS (SELECT 1 FROM AttackData.Hit t WHERE t.HitType = v.HitType);
GO

